import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"数学：错题边界与复盘","description":"用反例、代回与计数模型定位第一处错误，复核生日问题和旧方程答案。","frontmatter":{"title":"数学：错题边界与复盘","description":"用反例、代回与计数模型定位第一处错误，复核生日问题和旧方程答案。","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"专题笔记","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"数学：前置关系与代数起点","summary":"用反例、代回与计数模型定位第一处错误，复核生日问题和旧方程答案。","status":"active","related":[{"title":"八年级数学独立习题集","link":"/life/math/junior/grade-8/exercises","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 平方根、立方根与实数至一次函数与实际方案比较","link":"/life/math/junior/grade-8/exercises-part-01","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学独立习题集 · 三角形全等与对应关系至加权平均数与方差","link":"/life/math/junior/grade-8/exercises-part-02","kind":"习题与解析","scope":"general","audience":"general"},{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"八年级数学知识讲解","link":"/life/math/junior/grade-8/knowledge","kind":"知识讲解","scope":"general","audience":"general"}],"prev":{"text":"数学：概率与方程完整习题","link":"/life/math/exercises/workbook"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"数学：概率与方程完整习题","link":"/life/math/exercises/workbook"},"next":false},"headers":[],"relativePath":"life/math/exercises/mistakes.md","filePath":"life/math/exercises/mistakes.md"}'),s={name:"life/math/exercises/mistakes.md"};function n(o,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="数学-错题边界与复盘" tabindex="-1">数学：错题边界与复盘 <a class="header-anchor" href="#数学-错题边界与复盘" aria-label="Permalink to &quot;数学：错题边界与复盘&quot;">​</a></h1><p>需能代回方程检查解，并区分有序与无序选取。本页从平方反例、漏负根与计数模型开始，记录第一处错误，再核对旧笔记中的概率和方程答案；<a href="/life/math/exercises/workbook">独立习题</a>用于变式练习。</p><h2 id="counterexample" tabindex="-1">反例检查 <a class="header-anchor" href="#counterexample" aria-label="Permalink to &quot;反例检查 {#counterexample}&quot;">​</a></h2><p>数学 反例检查只需一个满足前提却不满足结论的例子，就能否定全称命题。命题“平方后数总变大”取x=1/2，平方1/4更小；命题“相关就有因果”则不属于单凭代数计算可证明的结论。</p><p>题：“若a²=b²，则a=b”是否成立？取a=1、b=-1即可否定。修正为实数下a=b或a=-b，若再限制a、b非负才推出相等。写反例时要同时核对前提，否则取一个不在定义域的数不构成反驳。</p><h2 id="errors" tabindex="-1">错题复盘 <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;错题复盘 {#errors}&quot;">​</a></h2><p>数学 错题复盘保留原推导的第一处不等价，而不只抄最终答案。例：x²=9→x=3，遗漏负根发生在开方那一步；正确解集为{3,-3}，代回都得9。</p><p>给错因标记“定义域”“算术”“模型”“推理”。把“4人选2人=12”用于无职务选组是模型错；3乘4算成7是算术错。下一道变式为5人选2人，答案10；若要求两职务则20。能解释为何除以2，比只记10更能说明理解。</p><h2 id="source-boundary" tabindex="-1">旧题边界 <a class="header-anchor" href="#source-boundary" aria-label="Permalink to &quot;旧题边界 {#source-boundary}&quot;">​</a></h2><p>数学 旧题边界保留可查的历史材料与已完成的原页校正，按公式、条件、答案分别核对。旧<a href="/life/math/applications/2-formula">公式速查</a>曾有缺括号及三角计算条件问题，本轮已在原页修正；旧<a href="/life/math/foundations/3-math">高等与离散笔记</a>的生日问题应先求全异概率，再取补事件。</p><p>23人生日至少重复概率的模型需假设生日独立且365天等可能；全异为365乘364一直到343，再除365的23次方，重复概率是1减该值。旧<a href="/life/math/foundations/operationsresearch">运筹学笔记</a>保留专题参考，马尔可夫长期唯一稳定分布还需要适当条件，不能照抄成无条件事实。</p><p>旧方程题的两处明确更正：2x+y=5、3x-y=1直接相加得5x=6，因此x=6/5、y=13/5，代回两式均成立；旧答7/8与3/8不能代回。x²+y²=25、x+y=7时，将第二式平方得49=25+2xy，因此xy=12，x和y为方程t²-7t+12=0的根3与4，解为(3,4)或(4,3)，不是(2,5)或(6,1)。遇到旧题先代回检查，不用历史答案替代推导。</p>',12)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
